-- Baseline schema, generated by Hibernate from the entities (ddl-auto=create on an
-- empty PostGIS 16-3.4 DB) and dumped with pg_dump --schema-only.
-- Every later schema change goes in a new V<n>__*.sql file; never edit this one.

CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE public.bid_sos (
    price numeric(10,2) NOT NULL,
    bid_at timestamp(6) without time zone,
    estimated_distance_m bigint,
    estimated_duration_s bigint,
    no_show_prompted_at timestamp(6) without time zone,
    responded_at timestamp(6) without time zone,
    bid_id uuid NOT NULL,
    mechanic_id uuid NOT NULL,
    sos_id uuid NOT NULL,
    estimated_distance_text character varying(255),
    estimated_duration_text character varying(255),
    status character varying(255) NOT NULL,
    CONSTRAINT bid_sos_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACCEPTED'::character varying, 'REJECTED'::character varying, 'CANCELLED'::character varying])::text[])))
);

CREATE TABLE public.feedback (
    rating numeric(2,1) NOT NULL,
    created_at timestamp(6) without time zone,
    id uuid NOT NULL,
    mechanic_id uuid NOT NULL,
    sos_id uuid NOT NULL,
    user_id uuid NOT NULL,
    comment text,
    CONSTRAINT feedback_rating_check CHECK (((rating >= 1.0) AND (rating <= 5.0)))
);

CREATE TABLE public.mechanic (
    available_status boolean NOT NULL,
    service_radius_km integer NOT NULL,
    location_moved_at timestamp(6) without time zone,
    location_updated_at timestamp(6) without time zone,
    current_h3_index character varying(16),
    id uuid NOT NULL,
    phone_number character varying(20) NOT NULL,
    email character varying(30),
    full_name character varying(30) NOT NULL,
    address text,
    mechanic_role character varying(255),
    referral_code character varying(255),
    base_location public.geography(Point,4326),
    current_location public.geography(Point,4326),
    CONSTRAINT mechanic_mechanic_role_check CHECK (((mechanic_role)::text = ANY ((ARRAY['UNDER_GARAGE'::character varying, 'FREELANCE'::character varying])::text[])))
);

CREATE TABLE public.mechanic_rate (
    rating_avg numeric(3,2),
    rating_count integer NOT NULL,
    created_at timestamp(6) without time zone NOT NULL,
    updated_at timestamp(6) without time zone NOT NULL,
    id uuid NOT NULL,
    mechanic_profile_id uuid NOT NULL
);

CREATE TABLE public.mechanic_skill (
    created_at timestamp(6) without time zone NOT NULL,
    id uuid NOT NULL,
    mechanic_profile_id uuid NOT NULL,
    vehicle_specialization character varying(255),
    skill_tags text[]
);

CREATE TABLE public.sos_media (
    size_bytes bigint,
    uploaded_at timestamp(6) without time zone,
    media_id uuid NOT NULL,
    sos_id uuid NOT NULL,
    uploaded_by_mechanic uuid,
    uploaded_by_user uuid,
    content_type character varying(255) NOT NULL,
    media_type character varying(255) NOT NULL,
    object_key character varying(255) NOT NULL,
    CONSTRAINT sos_media_check CHECK (((uploaded_by_user IS NOT NULL) OR (uploaded_by_mechanic IS NOT NULL))),
    CONSTRAINT sos_media_media_type_check CHECK (((media_type)::text = ANY ((ARRAY['PHOTO'::character varying, 'VIDEO'::character varying])::text[])))
);

CREATE TABLE public.sos_offer (
    bid_at timestamp(6) without time zone,
    offered_at timestamp(6) without time zone NOT NULL,
    id uuid NOT NULL,
    mechanic_id uuid NOT NULL,
    sos_id uuid NOT NULL
);

CREATE TABLE public.sos_request (
    broadcast_radius_km integer,
    rebroadcast_count integer DEFAULT 0 NOT NULL,
    bidding_expires_at timestamp(6) without time zone,
    created_at timestamp(6) without time zone,
    job_completed_at timestamp(6) without time zone,
    job_started_at timestamp(6) without time zone,
    updated_at timestamp(6) without time zone,
    sos_id uuid NOT NULL,
    user_id uuid NOT NULL,
    vehicle_id character varying(64) NOT NULL,
    description text,
    location_address text,
    problem_type character varying(255) NOT NULL,
    status character varying(255) NOT NULL,
    location public.geography(Point,4326) NOT NULL,
    CONSTRAINT sos_request_status_check CHECK (((status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACCEPTED'::character varying, 'ON_THE_WAY'::character varying, 'ARRIVED'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[])))
);

CREATE TABLE public.sos_status_history (
    approve_at timestamp(6) without time zone,
    change_at timestamp(6) without time zone NOT NULL,
    proposed_at timestamp(6) without time zone,
    approved_by uuid,
    id uuid NOT NULL,
    proposed_by uuid NOT NULL,
    sos_id uuid NOT NULL,
    approved_status character varying(255),
    from_status character varying(255) NOT NULL,
    to_status character varying(255) NOT NULL,
    CONSTRAINT sos_status_history_approved_status_check CHECK (((approved_status)::text = ANY ((ARRAY['PENDING_APPROVAL'::character varying, 'ACCEPTED'::character varying, 'REJECTED'::character varying])::text[]))),
    CONSTRAINT sos_status_history_from_status_check CHECK (((from_status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACCEPTED'::character varying, 'ON_THE_WAY'::character varying, 'ARRIVED'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[]))),
    CONSTRAINT sos_status_history_to_status_check CHECK (((to_status)::text = ANY ((ARRAY['PENDING'::character varying, 'ACCEPTED'::character varying, 'ON_THE_WAY'::character varying, 'ARRIVED'::character varying, 'IN_PROGRESS'::character varying, 'COMPLETED'::character varying, 'CANCELLED'::character varying, 'EXPIRED'::character varying])::text[])))
);

CREATE TABLE public.users (
    user_id uuid NOT NULL,
    name character varying(255) NOT NULL,
    phone character varying(255) NOT NULL,
    referer_code character varying(255),
    status character varying(255) NOT NULL,
    CONSTRAINT users_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'INACTIVE'::character varying, 'SUSPENDED'::character varying])::text[])))
);

CREATE TABLE public.vehicle (
    user_id uuid NOT NULL,
    id character varying(64) NOT NULL,
    car_brand character varying(255),
    car_model character varying(255),
    car_model_year character varying(255),
    fuel_type character varying(255),
    license_plate character varying(255),
    CONSTRAINT vehicle_fuel_type_check CHECK (((fuel_type)::text = ANY ((ARRAY['PETROL'::character varying, 'DIESEL'::character varying, 'HYBRID'::character varying, 'ELECTRIC'::character varying])::text[])))
);

